tasks.task:
Analise o codigo abaixo, identifique TODOS os bugs (logicos, de tipagem, de seguranca, de performance) e apresente uma versao corrigida e refatorada com TypeScript. Explique cada bug encontrado e a correcao.

```ts
// app.ts
import express from 'express';
const app = express();
app.use(express.json());

let users: any[] = [];
let nextId = 0;

app.get('/users', (req, res) => {
  const q = req.query.search;
  if (q) {
    res.json(users.filter(u => u.name.includes(q)));
  } else {
    res.json(users);
  }
});

app.post('/users', (req, res) => {
  const user = req.body;
  user.id = nextId++;
  users.push(user);
  res.json(user);
});

app.get('/users/:id', (req, res) => {
  const user = users.find(u => u.id === Number(req.params.id));
  res.json(user);
});

app.put('/users/:id', (req, res) => {
  const idx = users.findIndex(u => u.id === Number(req.params.id));
  if (idx !== -1) {
    users[idx] = { ...users[idx], ...req.body, id: Number(req.params.id) };
    res.json(users[idx]);
  } else {
    res.status(404).send();
  }
});

app.listen(3000);
```
